const j = $input.first().json;
const pick = function (frag) { const k = Object.keys(j).find(function (x) { return x.toLowerCase().indexOf(frag) === 0; }); return k ? String(j[k] || '').trim() : ''; };
const businessName = pick('business name');
const email = pick('your email').toLowerCase();
const phoneRaw = pick('phone number');
const d = phoneRaw.replace(/\D/g, '').slice(-10);
const phone = d.length === 10 ? '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6) : phoneRaw;
return [{ json: {
  source: 'ad_intake',
  businessName: businessName,
  nameKey: businessName.toLowerCase().replace(/[^a-z0-9]/g, ''),
  email: email,
  phone: phone,
  phoneDigits: d,
  offer: pick('your offer'),
  website: pick('website'),
  notes: pick('anything else'),
  hasLogo: Object.keys($input.first().binary || {}).length > 0
}, binary: $input.first().binary }];

