const inp = $('Normalize Submission').first().json;
let ai = {};
const raw = $('Write Ad Copy').first().json || {};
if (raw.offer_line) { ai = raw; } else if (raw.output && raw.output.offer_line) { ai = raw.output; } else { try { ai = JSON.parse(String(raw.text || '{}').replace(/^[^{]*/, '').replace(/[^}]*$/, '')); } catch (e) { ai = {}; } }
const rows = $input.all().map(function (i) { return i.json; });
const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); };
const digits = function (s) { return String(s || '').replace(/\D/g, '').slice(-10); };
const val = function (r, key) { return r[key] !== undefined ? r[key] : ''; };
let match = null;
for (const r of rows) {
  const e = String(val(r, 'property_customer_email') || '').toLowerCase();
  if (inp.email && e && e === inp.email) { match = r; break; }
}
if (!match) for (const r of rows) {
  const p = digits(val(r, 'property_phone'));
  if (inp.phoneDigits && p && p === inp.phoneDigits) { match = r; break; }
}
if (!match) for (const r of rows) {
  const n = norm(r.name || val(r, 'property_business_name'));
  if (n && inp.nameKey && n.length >= 5 && inp.nameKey.length >= 5 && (n === inp.nameKey || n.indexOf(inp.nameKey) >= 0 || inp.nameKey.indexOf(n) >= 0)) { match = r; break; }
}
const offerText = (ai.offer_line ? 'Card line: ' + ai.offer_line + ' | ' : '') + 'Owner wrote: ' + inp.offer + (inp.website ? ' | Website: ' + inp.website : '') + (inp.notes ? ' | Notes: ' + inp.notes : '');
const props = {
  'Sale Stage': { select: { name: 'Ad received' } },
  'Customer Email': { email: inp.email || null },
  'Ad Offer': { rich_text: [{ text: { content: offerText.slice(0, 1900) } }] },
  'Ad Phone': { phone_number: inp.phone || null }
};
const createProps = Object.assign({}, props, {
  'Business Name': { title: [{ text: { content: inp.businessName || 'Unknown business' } }] },
  'Call Notes': { rich_text: [{ text: { content: 'Created by the ad intake form. Not matched to an existing Call List row, check for a duplicate.' } }] }
});
return [{ json: {
  found: !!match,
  pageId: match ? match.id : '',
  pageUrl: match ? match.url : '',
  updateBody: { properties: props },
  createBody: { parent: { database_id: '5db44cc8-35d1-451e-bb69-2cd2ab6ffc3e' }, properties: createProps },
  ai: ai,
  inp: inp
} }];

const b = $('Normalize Submission').first().binary || {};
const out = {};
const keys = Object.keys(b);
if (keys.length) out.logo = b[keys[0]];
return [{ json: $input.first().json, binary: out }];
